    public void Apply(decimal amount) { }
    public void Commit() { }
    public void Dispose() { }
}

solution.Solution.cs:
public class Ledger(decimal opening)
{
    private Transaction? _open;

    public decimal Balance { get; private set; } = opening;

    public Transaction Begin()
    {
        if (_open != null) throw new InvalidOperationException("a transaction is already open");
        _open = new Transaction(this, Balance);
        return _open;
    }

    internal void Finish(Transaction tx, decimal? newBalance)
    {
        if (newBalance is decimal b) Balance = b;
        if (ReferenceEquals(_open, tx)) _open = null;
    }
}

public sealed class Transaction : IDisposable
{
    private readonly Ledger _ledger;
    private bool _committed, _disposed;

    internal Transaction(Ledger ledger, decimal start)
    {
        _ledger = ledger;
        Pending = start;
    }

    public decimal Pending { get; private set; }

    public void Apply(decimal amount)
    {
        ObjectDisposedException.ThrowIf(_disposed, this);
        if (_committed) throw new InvalidOperationException("already committed");
        Pending += amount;
    }

    public void Commit()
    {
        ObjectDisposedException.ThrowIf(_disposed, this);
        if (_committed) throw new InvalidOperationException("already committed");
        if (Pending < 0) throw new InvalidOperationException("would go negative");
        _committed = true;
        _ledger.Finish(this, Pending);
    }

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        _ledger.Finish(this, null);
    }
}

unitTests:
Test("commit applies the changes", () =>
{
    var ledger = new Ledger(100m);
    using (var tx = ledger.Begin())
    {
        tx.Apply(-30m);
        tx.Apply(5m);
        CheckEq(tx.Pending, 75m);
        CheckEq(ledger.Balance, 100m);
        tx.Commit();
    }
    CheckEq(ledger.Balance, 75m);
});

Test("leaving without commit rolls back", () =>
{
    var ledger = new Ledger(75m);
    using (var tx = ledger.Begin())
    {
        tx.Apply(-500m);
    }
    CheckEq(ledger.Balance, 75m);
    try
    {
        using var tx = ledger.Begin();
        tx.Apply(10m);
        throw new TimeoutException("something failed");
    }
    catch (TimeoutException) { }
    CheckEq(ledger.Balance, 75m);
});

Test("rules", () =>
{
    var ledger = new Ledger(10m);
    var tx = ledger.Begin();
    CheckThrows<InvalidOperationException>(() => ledger.Begin());
    tx.Apply(-20m);
    CheckThrows<InvalidOperationException>(() => tx.Commit());
    CheckEq(ledger.Balance, 10m);
    tx.Apply(15m);
    tx.Commit();
    CheckThrows<InvalidOperationException>(() => tx.Commit());
    tx.Dispose();
    tx.Dispose();
    CheckThrows<ObjectDisposedException>(() => tx.Apply(1m));
    CheckEq(ledger.Balance, 5m);
    using var next = ledger.Begin();
    CheckEq(next.Pending, 5m);
});

